		ObjectNode a = structuredOwner();
		int id = createOwnerOk(a);
		deleteOwner(id); // A is soft-deleted
		createOwner(a.deepCopy()).andExpect(status().is2xxSuccessful()); // only match is deleted -> allowed
	}
}

